def orbit(r,c,n):
 return {(r,c),(c,r),(r,n-1-c),(n-1-r,c),(n-1-r,n-1-c),(c,n-1-r),(n-1-c,r),(n-1-c,n-1-r)}
def transform(grid):
 n=len(grid); out=[row[:] for row in grid]
 for r in range(n):
  for c in range(n):
   if grid[r][c]==2:
    vals=[grid[rr][cc] for rr,cc in orbit(r,c,n) if grid[rr][cc]!=2]
    if not vals or len(set(vals))>1: raise ValueError((r,c,vals))
    out[r][c]=vals[0]
 return out
